1	// Scope-blind mechanism: apply the project's severity overrides and acceptances,
2	// order blocking-first, print each finding, and print the one-line summary.
3	// Returns the blocking count so a runner's exit code is `blocking ? 1 : 0`.
4	// `scopeLabel` only names the run in the summary line (e.g. "world" / "work") —
5	// this file carries no scope logic of its own.
6	import { applyConfig, render } from './helpers/findings.mjs';
7	
8	export function reportFindings(findings, config, { scopeLabel, mode, baseRef }) {
9	  const resolved = applyConfig(findings, config)
10	    .sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'blocking' ? -1 : 1));
11	  for (const f of resolved) console.log(`${render(f)}\n`);
12	  const blocking = resolved.filter((f) => f.severity === 'blocking').length;
13	  const advisory = resolved.length - blocking;
14	  if (resolved.length) {
15	    console.log(`${blocking} blocking, ${advisory} advisory (${scopeLabel} scope: ${mode}${baseRef ? ` vs ${baseRef}` : ''}).`);
16	  }
17	  return blocking;
18	}
19

